window.TUTODEMY_REVIEWERS=[{"id":"math-m1","category":"Mathematics","domain":"M1","title":"Number Sense & Basic Algebra","access":"Free","summary":"Build accurate no-calculator computation before moving to longer word problems.","points":["Follow the order of operations.","Translate fractions, ratios, and percentages into equivalent forms.","Use unit rates and proportional reasoning.","Check magnitude and units before selecting an answer."],"practice":"M1","topics":[{"id":"order-of-operations","title":"Order of Operations","summary":"Use PEMDAS correctly and handle multiplication/division or addition/subtraction from left to right.","questionTopics":["Order of operations"],"video":{"title":"Order of Operations - Made Easy!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=saTBf8AO4Ok","source":"YouTube"},"questionCount":11},{"id":"fractions","title":"Fractions","summary":"Review fraction operations, simplification, and common fraction word problems.","questionTopics":["Fractions","Fraction and budget problems","Fraction word problems"],"video":{"title":"Fractions Basic Introduction - Adding, Subtracting, Multiplying & Dividing","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=GvLIEiqxS6s","source":"YouTube"},"questionCount":13},{"id":"percentages","title":"Percentages","summary":"Work with percent of a number, reverse percentages, percent change, and common applications.","questionTopics":["Percent","Reverse percentage","Successive percent change","Successive percentages","Percent of time","Profit and loss"],"video":{"title":"Percentages Made Easy!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=WYWPuG-8U5Q","source":"YouTube"},"questionCount":16},{"id":"ratio-proportion","title":"Ratio & Proportion","summary":"Set up equivalent ratios, solve proportions, and apply unit-rate reasoning.","questionTopics":["Ratio and proportion","Proportion","Ratio","Ratios and mixtures","Unit rate"],"video":{"title":"Ratio and Proportion Word Problems - Math","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=JOZSFwuyqok","source":"YouTube"},"questionCount":14}],"studyGuide":{"intro":"Master the arithmetic foundations that appear repeatedly in CET-style computation and word problems. Focus on accuracy, signs, equivalent forms, and proportional reasoning.","highYield":[{"title":"Order of Operations & Integers","points":["Use grouping symbols first, then exponents, then multiplication/division from left to right, then addition/subtraction from left to right.","A negative sign attached to a number is part of that number; subtraction and a negative value are not always the same operation.","For consecutive integers, represent them as n, n+1, n+2; for consecutive odd/even integers, use n, n+2, n+4."],"formula":"PEMDAS: ( ) → exponents → ×/÷ left-to-right → +/− left-to-right","example":{"question":"Evaluate 18 ÷ 3 × 2 + 4.","steps":["18 ÷ 3 = 6","6 × 2 = 12","12 + 4 = 16"],"answer":"16"},"trap":"Do not automatically multiply before dividing. Multiplication and division have the same priority, so work left to right."},{"title":"Fractions","points":["For addition/subtraction, use a common denominator before combining numerators.","For multiplication, multiply numerators and denominators, then simplify.","For division, multiply by the reciprocal of the divisor.","In word problems, identify whether the fraction represents a part of a whole, a remaining part, or a rate."],"formula":"a/b ÷ c/d = a/b × d/c","example":{"question":"Compute 3/4 + 2/3.","steps":["LCM of 4 and 3 is 12","3/4 = 9/12 and 2/3 = 8/12","9/12 + 8/12 = 17/12"],"answer":"17/12 or 1 5/12"},"trap":"Never add denominators directly when adding fractions."},{"title":"Percentages","points":["Convert a percent to decimal by dividing by 100.","To find a percent of a number, multiply the whole by the decimal form.","For reverse percentage, divide the known final amount by the remaining/original percent factor.","Percent change always uses the original value in the denominator."],"formula":"percent change = (new − original) / original × 100%","example":{"question":"A price rises from ₱800 to ₱920. Find the percent increase.","steps":["Increase = 920 − 800 = 120","120 ÷ 800 = 0.15","0.15 × 100% = 15%"],"answer":"15%"},"trap":"For percent change, dividing by the new value instead of the original value gives the wrong result."},{"title":"Ratio, Proportion & Unit Rate","points":["Keep compared quantities in the same order on both sides of a proportion.","Reduce ratios when useful, but keep units visible until the final step.","A unit rate expresses a quantity per 1 unit, such as pesos per item or kilometers per hour.","For mixtures, track the amount of each component rather than only the total."],"formula":"a/b = c/d  ⇒  ad = bc","example":{"question":"If 3 notebooks cost ₱90, how much do 5 notebooks cost at the same rate?","steps":["Unit rate = 90 ÷ 3 = ₱30 per notebook","5 × 30 = 150"],"answer":"₱150"},"trap":"A proportion fails if the order of the quantities is reversed on only one side."}],"quickRecall":["What operations share the same priority in PEMDAS?","What must be equal before adding or subtracting fractions?","What value belongs in the denominator of percent change?","What does a unit rate mean?"],"checklist":["I can evaluate expressions with mixed operations and negative numbers.","I can add, subtract, multiply, and divide fractions.","I can solve percent-of, reverse-percent, and percent-change problems.","I can solve ratios, proportions, unit rates, and simple mixture problems."]}},{"id":"math-m2","category":"Mathematics","domain":"M2","title":"Intermediate Algebra","access":"Free","summary":"Turn verbal relationships into equations, then solve with controlled algebraic steps.","points":["Combine like terms before isolating variables.","Use elimination or substitution for systems.","Recognize factoring patterns.","Check a proposed solution in the original equation."],"practice":"M2","topics":[{"id":"linear-equations","title":"Linear Equations","summary":"Translate relationships into equations, isolate the variable, and check the solution.","questionTopics":["Linear equations","Algebraic expressions","Percent and linear modeling"],"video":{"title":"How To Solve Linear Equations In Algebra","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=7DPWeBszNSM","source":"YouTube"},"questionCount":18},{"id":"systems-of-equations","title":"Systems of Equations","summary":"Solve two-variable systems using substitution or elimination.","questionTopics":["Systems of equations"],"video":{"title":"Solving Systems of Equations by Elimination & Substitution","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=oKqtgz2eo-Y","source":"YouTube"},"questionCount":10},{"id":"exponents","title":"Exponents","summary":"Apply exponent rules carefully when multiplying, dividing, and simplifying powers.","questionTopics":["Exponents"],"video":{"title":"Properties of Exponents - Algebra 2","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=etMK3xViMAc","source":"YouTube"},"questionCount":10},{"id":"quadratic-equations","title":"Quadratic Equations","summary":"Recognize factorable quadratics and use the zero-product principle to find roots.","questionTopics":["Quadratic equations"],"video":{"title":"How To Solve Quadratic Equations By Factoring","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=aj4akBeGjuo","source":"YouTube"},"questionCount":15},{"id":"distance-rate-time","title":"Distance, Rate & Time","summary":"Use d = rt and organize motion information before solving travel problems.","questionTopics":["Distance-rate-time"],"video":{"title":"Distance, Rate and Time","channel":"Krista King Math","url":"https://www.youtube.com/watch?v=Zl6zUBCgLbU","source":"YouTube"},"questionCount":10}],"studyGuide":{"intro":"Translate relationships into algebra, choose an efficient solving method, and verify solutions. Most errors here come from sign mistakes, distribution errors, or using a correct method on the wrong equation form.","highYield":[{"title":"Linear Equations","points":["Simplify both sides before isolating the variable.","Apply the same operation to both sides of an equation.","Distribute multiplication across every term inside parentheses.","Translate verbal phrases carefully: 'less than' reverses the order."],"formula":"ax + b = c  ⇒  x = (c − b)/a","example":{"question":"Solve 3(x − 2) + 4 = 16.","steps":["3x − 6 + 4 = 16","3x − 2 = 16","3x = 18","x = 6"],"answer":"x = 6"},"trap":"A negative sign outside parentheses changes every sign inside when distributed."},{"title":"Systems of Equations","points":["Use substitution when one equation already isolates a variable or can do so easily.","Use elimination when coefficients can be made opposites quickly.","The solution is an ordered pair that satisfies both equations."],"formula":"Solve the two equations simultaneously for the same x and y.","example":{"question":"Solve x + y = 9 and x − y = 3.","steps":["Add the equations: 2x = 12","x = 6","Substitute: 6 + y = 9","y = 3"],"answer":"(6, 3)"},"trap":"After eliminating one variable, always substitute back to obtain the second variable."},{"title":"Exponents","points":["When multiplying like bases, add exponents.","When dividing like bases, subtract exponents.","When raising a power to a power, multiply exponents.","A negative exponent means reciprocal; a zero exponent gives 1 for a nonzero base."],"formula":"a^m·a^n=a^(m+n), a^m/a^n=a^(m−n), (a^m)^n=a^(mn)","example":{"question":"Simplify (x³ · x⁵) / x².","steps":["x³ · x⁵ = x⁸","x⁸ ÷ x² = x⁶"],"answer":"x⁶"},"trap":"Do not add exponents when adding terms: x² + x³ cannot be simplified to x⁵."},{"title":"Quadratic Equations","points":["Move all terms to one side so the equation equals zero before factoring.","Use the zero-product principle after writing the quadratic as a product of factors.","Check whether a common factor can be removed first.","If factoring is not convenient, the quadratic formula is a reliable fallback."],"formula":"ax²+bx+c=0;  x = (−b ± √(b²−4ac))/(2a)","example":{"question":"Solve x² − 5x + 6 = 0.","steps":["Find factors of 6 that sum to −5","(x − 2)(x − 3) = 0","x = 2 or x = 3"],"answer":"x = 2, 3"},"trap":"Factoring only works with the zero-product principle when one side of the equation is zero."},{"title":"Distance, Rate & Time","points":["Write the relationship d = rt before inserting numbers.","Keep units consistent; convert minutes to hours when the rate is in km/h.","For two moving objects, write a separate distance expression for each.","Opposite directions often involve adding distances; same-direction catch-up problems often involve subtracting rates."],"formula":"d = rt,  r = d/t,  t = d/r","example":{"question":"A car travels 180 km at 60 km/h. How long does the trip take?","steps":["t = d/r","t = 180/60","t = 3"],"answer":"3 hours"},"trap":"Do not mix minutes with a per-hour rate without converting units."}],"quickRecall":["What should you do before isolating a variable in a messy linear equation?","When is elimination usually faster than substitution?","What happens to exponents when multiplying like bases?","What must a quadratic equal before using the zero-product principle?","What is the basic relationship among distance, rate, and time?"],"checklist":["I can solve multi-step linear equations and translate word statements into equations.","I can solve systems using substitution or elimination.","I can simplify expressions using exponent laws.","I can factor and solve common quadratic equations.","I can solve distance-rate-time problems with consistent units."]}},{"id":"math-m3","category":"Mathematics","domain":"M3","title":"Geometry & Trigonometry","access":"Premium","summary":"Connect diagrams with definitions, properties, and measurement formulas.","points":["Mark known lengths and angles.","Separate perimeter, area, and volume units.","Use similar triangles and the Pythagorean theorem.","Treat diagrams as not necessarily drawn to scale."],"practice":"M3","topics":[{"id":"triangle-angles","title":"Triangle Angles","summary":"Use angle relationships and the 180° triangle angle sum.","questionTopics":["Triangle angles"],"video":{"title":"Triangles - Basic Introduction, Geometry","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=q7vI2oXL0gQ","source":"YouTube"},"questionCount":10},{"id":"pythagorean-theorem","title":"Pythagorean Theorem","summary":"Find missing right-triangle side lengths using a² + b² = c².","questionTopics":["Pythagorean theorem"],"video":{"title":"Pythagorean Theorem","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=d8EA5TxGzcY","source":"YouTube"},"questionCount":10},{"id":"area-perimeter","title":"Area & Perimeter","summary":"Choose the correct measurement formula and keep linear and square units distinct.","questionTopics":["Area and perimeter"],"video":{"title":"Area and Perimeter","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=gtMKsFXjLHw","source":"YouTube"},"questionCount":10},{"id":"circles","title":"Circles","summary":"Connect radius and diameter, then calculate circumference and area.","questionTopics":["Circles"],"video":{"title":"Circles - Area, Circumference, Radius & Diameter Explained!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=D4nGkWOPb6M","source":"YouTube"},"questionCount":10},{"id":"basic-trigonometry","title":"Basic Trigonometry","summary":"Use sine, cosine, and tangent to solve right-triangle problems.","questionTopics":["Basic trigonometry"],"video":{"title":"Trigonometry For Beginners!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=PUB0TaZ7bhA","source":"YouTube"},"questionCount":10}],"studyGuide":{"intro":"Convert diagrams into known relationships and formulas. Mark given values first, identify the figure, then choose the formula or theorem that directly applies.","highYield":[{"title":"Angles & Triangles","points":["The interior angles of a triangle sum to 180°.","Angles on a straight line sum to 180°; angles around a point sum to 360°.","Complementary angles sum to 90° and supplementary angles sum to 180°.","An exterior angle of a triangle equals the sum of the two remote interior angles."],"formula":"A + B + C = 180°","example":{"question":"Two angles of a triangle are 48° and 67°. Find the third angle.","steps":["48 + 67 = 115","180 − 115 = 65"],"answer":"65°"},"trap":"Do not assume a diagram is drawn to scale; rely on given values and geometric rules."},{"title":"Pythagorean Theorem","points":["Use the theorem only for right triangles.","The hypotenuse is opposite the right angle and is always the longest side.","If solving for a leg, subtract the known leg square from the hypotenuse square."],"formula":"a² + b² = c²","example":{"question":"A right triangle has legs 6 and 8. Find the hypotenuse.","steps":["c² = 6² + 8²","c² = 36 + 64 = 100","c = 10"],"answer":"10"},"trap":"Never treat an arbitrary side as c; c must be the hypotenuse."},{"title":"Area & Perimeter","points":["Perimeter measures boundary length; area measures surface covered.","Keep perimeter in linear units and area in square units.","Break composite figures into familiar shapes when necessary."],"formula":"Rectangle: A=lw, P=2l+2w; Triangle: A=½bh","example":{"question":"Find the area of a triangle with base 12 cm and height 7 cm.","steps":["A = ½bh","A = ½(12)(7)","A = 42"],"answer":"42 cm²"},"trap":"Do not use a slanted side as the height unless it is perpendicular to the chosen base."},{"title":"Circles","points":["Diameter is twice the radius.","Circumference is a length; area is a square-unit measure.","If given a diameter, divide by 2 before using an area formula."],"formula":"d=2r, C=2πr=πd, A=πr²","example":{"question":"Find the area of a circle with diameter 10 cm.","steps":["Radius = 10/2 = 5","A = π(5²)","A = 25π"],"answer":"25π cm²"},"trap":"A very common mistake is substituting the diameter as r."},{"title":"Basic Trigonometry","points":["Choose the ratio based on the sides relative to the reference angle.","SOH: sin θ = opposite/hypotenuse.","CAH: cos θ = adjacent/hypotenuse.","TOA: tan θ = opposite/adjacent.","Use inverse trig when solving for an angle."],"formula":"sin=O/H, cos=A/H, tan=O/A","example":{"question":"Relative to angle θ, opposite = 6 and adjacent = 8. Find tan θ.","steps":["tan θ = opposite/adjacent","tan θ = 6/8","Simplify to 3/4"],"answer":"3/4"},"trap":"Opposite and adjacent depend on the chosen reference angle; they are not fixed labels."}],"quickRecall":["What is the sum of a triangle's interior angles?","Which side is c in the Pythagorean theorem?","How do the units of area differ from perimeter?","What is the relationship between radius and diameter?","Which trig ratio uses opposite and adjacent?"],"checklist":["I can solve missing-angle problems using basic angle relationships.","I can use the Pythagorean theorem on right triangles.","I can choose correct area/perimeter formulas and units.","I can solve circle problems using radius, diameter, circumference, and area.","I can select and use sine, cosine, or tangent."]}},{"id":"math-m4","category":"Mathematics","domain":"M4","title":"Functions, Statistics & Probability","access":"Premium","summary":"Interpret patterns and data instead of memorizing isolated formulas.","points":["Identify input, output, and rule.","Classify a sequence before choosing a formula.","Distinguish mean, median, and range.","Define the sample space before computing probability."],"practice":"M4","topics":[{"id":"mean-median-range","title":"Mean, Median & Range","summary":"Compute common summary statistics and interpret averages carefully.","questionTopics":["Mean","Average","Weighted average"],"video":{"title":"How to Calculate Mean, Median, Mode, and Range","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=A1mQ9kD-i9I","source":"YouTube"},"questionCount":12},{"id":"arithmetic-sequences","title":"Arithmetic Sequences","summary":"Identify the common difference and use an nth-term rule to continue a sequence.","questionTopics":["Arithmetic sequences"],"video":{"title":"Arithmetic Sequences and Arithmetic Series - Basic Introduction","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=XZJdyPkCxuE","source":"YouTube"},"questionCount":10},{"id":"functions","title":"Functions","summary":"Evaluate a function by substituting the input into the stated rule.","questionTopics":["Functions"],"video":{"title":"Evaluating Functions - Basic Introduction","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=HyNie_PYgsY","source":"YouTube"},"questionCount":10},{"id":"probability","title":"Probability","summary":"Define the sample space first, then compare favorable outcomes with all possible outcomes.","questionTopics":["Probability"],"video":{"title":"Probability Explained!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=UORztmWGY6Q","source":"YouTube"},"questionCount":10}],"studyGuide":{"intro":"Interpret rules, patterns, and data before calculating. These questions reward careful reading: identify what each value represents, then apply the simplest valid relationship.","highYield":[{"title":"Functions","points":["A function assigns an output to an input according to a rule.","To evaluate f(a), replace every x in the rule with a before simplifying.","Keep parentheses around substituted negative values."],"formula":"If f(x)=2x+3, then f(a)=2a+3","example":{"question":"If f(x)=3x−4, find f(5).","steps":["Substitute x = 5","f(5) = 3(5) − 4","15 − 4 = 11"],"answer":"11"},"trap":"f(5) means evaluate the function at 5; it does not mean f × 5."},{"title":"Arithmetic Sequences","points":["An arithmetic sequence has a constant difference between consecutive terms.","Find the common difference before using the nth-term formula.","The first term is a₁, not a₀, unless the problem explicitly defines otherwise."],"formula":"aₙ = a₁ + (n−1)d","example":{"question":"Find the 10th term of 4, 7, 10, 13, ...","steps":["a₁ = 4, d = 3","a₁₀ = 4 + (10−1)(3)","4 + 27 = 31"],"answer":"31"},"trap":"Using nd instead of (n−1)d shifts every term by one step."},{"title":"Mean, Median & Weighted Average","points":["Mean = total of values ÷ number of values.","Median is the middle value after ordering the data.","For an even number of values, median is the mean of the two middle values.","A weighted average gives different importance to different values."],"formula":"weighted mean = Σ(value × weight) / Σ(weights)","example":{"question":"Scores 80 and 90 have weights 40% and 60%. Find the weighted average.","steps":["80(0.40) = 32","90(0.60) = 54","32 + 54 = 86"],"answer":"86"},"trap":"Do not compute a simple mean when the problem gives unequal weights."},{"title":"Probability","points":["Define the sample space before counting favorable outcomes.","For equally likely outcomes, probability = favorable outcomes ÷ total outcomes.","A probability must lie from 0 to 1, or 0% to 100%.","Check whether the problem changes the sample space after an event."],"formula":"P(event) = favorable outcomes / total possible outcomes","example":{"question":"A fair die is rolled. What is the probability of rolling an even number?","steps":["Sample space: {1,2,3,4,5,6}","Even outcomes: {2,4,6}","3 favorable out of 6 total"],"answer":"1/2"},"trap":"Counting favorable outcomes correctly is not enough if the total sample space is wrong."}],"quickRecall":["What does f(3) tell you to do?","What identifies an arithmetic sequence?","When must data be ordered before finding a statistic?","What is different about a weighted average?","What should you define before computing a probability?"],"checklist":["I can evaluate functions for positive and negative inputs.","I can identify and extend arithmetic sequences and find the nth term.","I can compute mean, median, range, and weighted averages.","I can define a sample space and compute simple probabilities."]}},{"id":"lang-l1","category":"Language & Reading","domain":"L1","title":"Grammar & General Usage","access":"Free","summary":"Locate the grammatical structure first; do not choose an answer only because it sounds familiar.","points":["Identify the true subject and verb.","Check pronoun function and reference.","Maintain tense and point of view.","Use standard English and Filipino forms."],"practice":"L1","topics":[{"id":"subject-verb-agreement","title":"Subject–Verb Agreement","summary":"Match the verb with the true subject, including tricky compound and intervening phrases.","questionTopics":["Subject–verb agreement","Agreement with neither/nor"],"video":{"title":"Subject-verb agreement | Syntax","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=4fMipjAnlRk","source":"YouTube"},"questionCount":22},{"id":"pronouns","title":"Pronouns: Case & Reference","summary":"Choose correct subject/object pronouns and keep pronoun reference clear.","questionTopics":["Pronouns and verb forms","Pronoun case","Pronoun reference","Relative pronouns"],"video":{"title":"Subject and object pronouns | Grammar","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=q5HmV3Czl6g","source":"YouTube"},"questionCount":23},{"id":"verb-tenses","title":"English Verb Tenses","summary":"Use verb tense consistently and recognize how time changes verb form.","questionTopics":["Sequence of tenses","Conditional sentences","Subjunctive mood"],"video":{"title":"Introduction to verb tense | Grammar","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=faUvT7zfsyk","source":"YouTube"},"questionCount":3},{"id":"ng-vs-nang","title":"Ng vs Nang & Filipino Markers","summary":"Distinguish ng and nang and review marker use in standard Filipino sentences.","questionTopics":["Ng and nang","Filipino markers","Standard Filipino form"],"video":{"title":"Tagalog Grammar Lesson: NG vs NANG","channel":"Talk to Me in Tagalog","url":"https://www.youtube.com/watch?v=4PZ3m2KTFjk","source":"YouTube"},"questionCount":3},{"id":"aspekto-ng-pandiwa","title":"Aspekto ng Pandiwa","summary":"Review naganap, nagaganap, and magaganap forms and identify the time of an action.","questionTopics":["Filipino verb aspect"],"video":{"title":"ASPEKTO NG PANDIWA | Filipino 8","channel":"ARALIN SA FILIPINO","url":"https://www.youtube.com/watch?v=-wcExORDftk","source":"YouTube"},"questionCount":1}],"studyGuide":{"intro":"Focus on the grammatical relationship first: subject–verb agreement, pronoun form, verb tense, and standard Filipino usage. Avoid choosing an answer only because it sounds familiar.","highYield":[{"title":"Subject–Verb Agreement","points":["A singular subject takes a singular verb; a plural subject takes a plural verb.","Ignore interrupting phrases when identifying the true subject.","With either/or and neither/nor, agreement often follows the nearer subject.","Indefinite pronouns such as each, everyone, and anybody are usually singular."],"formula":"Find the true subject first → determine singular/plural → match the verb.","example":{"question":"Choose the correct verb: The list of requirements ___ on the table.","steps":["The true subject is list.","List is singular.","Use the singular verb is."],"answer":"The list of requirements is on the table."},"trap":"Do not match the verb with the nearest noun if that noun is only inside a modifying phrase."},{"title":"Pronouns: Case & Reference","points":["Use subject pronouns as subjects and object pronouns after verbs or prepositions.","A pronoun must clearly refer to one specific antecedent.","Match pronouns with their antecedents in number and person.","Use who for subject function and whom for object function when standard formal usage requires it."],"formula":"Subject: I/he/she/we/they · Object: me/him/her/us/them","example":{"question":"Choose the correct form: The coach spoke to Ana and ___.","steps":["The pronoun follows the preposition to.","Objects of prepositions use object pronouns.","Use me, not I."],"answer":"The coach spoke to Ana and me."},"trap":"A compound phrase does not automatically require I; remove the other noun and test the sentence."},{"title":"Verb Tense, Conditionals & Mood","points":["Keep tense consistent unless the time relationship genuinely changes.","Use past tense for completed actions and present tense for current/general truths.","In unreal present conditions, standard formal English commonly uses were.","Sequence of tenses should reflect the actual timing of events."],"formula":"Choose tense from the timeline, not from the nearest verb.","example":{"question":"Complete: If I ___ more time, I would join the review session.","steps":["The condition is hypothetical, not a real present fact.","Use the subjunctive form were."],"answer":"If I were given more time, I would join the review session."},"trap":"Do not shift tense just because another verb appears nearby; first identify the time of each action."},{"title":"Ng vs Nang & Filipino Markers","points":["Ng commonly marks possession, object, or quantity relationships.","Nang commonly answers how/when or connects repeated actions and certain adverbial uses.","Use Filipino markers according to grammatical role, not sound alone.","Check the entire phrase because meaning determines the correct marker."],"formula":"Ng → possession/object/quantity · Nang → manner/time/adverbial use","example":{"question":"Piliin ang tama: Tumakbo siya ___ mabilis.","steps":["The phrase describes how the action was done.","The word functions adverbially.","Use nang."],"answer":"Tumakbo siya nang mabilis."},"trap":"Do not choose ng or nang by pronunciation; identify the grammatical function first."},{"title":"Aspekto ng Pandiwa","points":["Perpektibo/naganap refers to a completed action.","Imperpektibo/nagaganap refers to an ongoing action.","Kontemplatibo/magaganap refers to an action that has not yet happened.","Look for both verb form and time markers in the sentence."],"formula":"Naganap → tapos na · Nagaganap → ginagawa ngayon · Magaganap → gagawin pa","example":{"question":"Anong aspekto ang pandiwang 'nag-aaral'?","steps":["The action is ongoing.","The reduplicated form indicates continuing action."],"answer":"Nagaganap / imperpektibo"},"trap":"Do not rely on a single prefix only; some verb forms require reading the whole word and sentence."}],"quickRecall":["How do you find the true subject when a phrase interrupts the sentence?","When should an object pronoun be used?","What should determine a verb tense: nearby words or the actual timeline?","What is one common function of nang?","Which aspect refers to an ongoing action?"],"checklist":["I can identify the true subject and choose the matching verb.","I can choose correct pronoun case and identify unclear pronoun reference.","I can keep verb tense and mood consistent with meaning.","I can distinguish common uses of ng and nang.","I can identify the aspect of a Filipino verb."]}},{"id":"lang-l2","category":"Language & Reading","domain":"L2","title":"Syntax & Mechanics","access":"Free","summary":"Use punctuation and sentence structure to express relationships clearly.","points":["Separate complete thoughts correctly.","Use commas around nonessential information.","Maintain parallel form.","Remove dangling modifiers and ambiguous references."],"practice":"L2","topics":[{"id":"sentence-fragments","title":"Sentence Fragments","summary":"Check whether a sentence has a complete subject, predicate, and independent thought.","questionTopics":["Syntax and mechanics","Sentence fragments"],"video":{"title":"Recognizing fragments | Syntax","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=xpoZBnXHg3E","source":"YouTube"},"questionCount":21},{"id":"run-ons-comma-splices","title":"Run-ons & Comma Splices","summary":"Separate independent clauses using correct punctuation and conjunctions.","questionTopics":["Syntax and mechanics","Run-on sentences"],"video":{"title":"Run-ons and comma splices | Syntax","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=Fh45mhVsZrU","source":"YouTube"},"questionCount":21},{"id":"semicolons","title":"Semicolons & Clause Punctuation","summary":"Use semicolons to connect closely related independent clauses and avoid punctuation errors.","questionTopics":["Syntax and mechanics","Semicolons","Colons"],"video":{"title":"Introduction to the semicolon | Punctuation","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=41XNKfR56OY","source":"YouTube"},"questionCount":22},{"id":"parallel-structure","title":"Parallel Structure","summary":"Keep items in lists, comparisons, and paired constructions in the same grammatical form.","questionTopics":["Syntax and mechanics","Parallel structure","Logical comparison"],"video":{"title":"Parallel structure | Syntax","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=2l2FgUrln1A","source":"YouTube"},"questionCount":22},{"id":"modifiers-clarity","title":"Modifiers & Sentence Clarity","summary":"Place modifying words and phrases beside the ideas they actually describe.","questionTopics":["Syntax and mechanics","Modifier placement","Pronoun ambiguity","Sentence concision","Nonessential elements"],"video":{"title":"Dangling modifiers | Syntax","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=SjunMcrXgE0","source":"YouTube"},"questionCount":24}],"studyGuide":{"intro":"Treat punctuation and sentence structure as tools for expressing relationships between ideas. First identify complete clauses, then decide how they should be connected.","highYield":[{"title":"Sentence Fragments","points":["A complete sentence normally needs a subject, a finite verb, and a complete thought.","Dependent clauses cannot usually stand alone.","Introductory phrases may look complete but still lack a main clause.","Fix a fragment by attaching it to a complete sentence or supplying the missing element."],"formula":"Complete sentence = independent clause with a complete thought","example":{"question":"Identify the problem: Because the exam started early.","steps":["Because introduces a dependent clause.","There is no independent clause completing the thought."],"answer":"It is a sentence fragment."},"trap":"A group of words can contain both a subject and verb and still be a fragment if it begins with a subordinating word."},{"title":"Run-ons & Comma Splices","points":["Two independent clauses cannot be joined by only a comma.","Use a period, semicolon, or comma plus coordinating conjunction.","Check whether each side can stand as a complete sentence."],"formula":"IC + ; + IC  OR  IC + , + FANBOYS + IC","example":{"question":"Fix: The review was difficult, I finished it.","steps":["Both sides are independent clauses.","A comma alone is not enough.","Add a coordinating conjunction."],"answer":"The review was difficult, but I finished it."},"trap":"A long sentence is not automatically a run-on; the problem is incorrect joining of independent clauses."},{"title":"Semicolons, Colons & Nonessential Elements","points":["A semicolon can join closely related independent clauses.","A colon usually follows a complete clause and introduces a list, explanation, or example.","Nonessential information is commonly set off by commas.","Essential information should not be separated in a way that changes meaning."],"formula":"Semicolon joins complete clauses; colon introduces after a complete clause.","example":{"question":"Choose the punctuation: I brought three things ___ pencils, paper, and a calculator.","steps":["The first part is a complete clause.","The second part is a list explaining three things.","Use a colon."],"answer":"I brought three things: pencils, paper, and a calculator."},"trap":"Do not place a colon immediately after a verb if the words before it do not form a complete clause."},{"title":"Parallel Structure & Logical Comparison","points":["Items in a list or paired construction should use the same grammatical form.","Compare like with like: person to person, action to action, quantity to quantity.","Watch correlative pairs such as not only/but also and either/or."],"formula":"Match grammatical form across coordinated items.","example":{"question":"Improve: She likes reading, to solve problems, and writing notes.","steps":["The list mixes -ing forms with an infinitive.","Use one consistent form."],"answer":"She likes reading, solving problems, and writing notes."},"trap":"A sentence may be grammatically understandable but still be nonparallel."},{"title":"Modifiers, Ambiguity & Concision","points":["Place a modifier beside the word or idea it describes.","A dangling modifier has no clear word to modify.","Remove unnecessary repetition without deleting meaning.","Pronouns and descriptive phrases should have one clear referent."],"formula":"Modifier → place it next to the intended target.","example":{"question":"Fix: Walking to class, the rain started.","steps":["The sentence suggests the rain was walking.","Supply the actual person doing the walking."],"answer":"Walking to class, I noticed that the rain started."},"trap":"Moving a modifier can completely change who or what performs the action."}],"quickRecall":["Can a dependent clause stand alone as a sentence?","What punctuation can join two related independent clauses without a conjunction?","What must usually come before a colon?","What does parallel structure require?","Where should a modifier be placed?"],"checklist":["I can distinguish complete sentences from fragments.","I can repair run-ons and comma splices.","I can use semicolons, colons, and commas correctly in common structures.","I can recognize nonparallel construction and illogical comparisons.","I can identify dangling/misplaced modifiers and unclear wording."]}},{"id":"lang-l3","category":"Language & Reading","domain":"L3","title":"Vocabulary & Diction","access":"Premium","summary":"Use context, word parts, and relationships to identify the most precise meaning.","points":["Read the entire sentence before choosing.","Check denotation and tone.","Match the required part of speech.","Prefer precise words appropriate to the audience."],"practice":"L3","topics":[{"id":"vocabulary-context","title":"Vocabulary in Context","summary":"Use surrounding definitions, examples, synonyms, antonyms, and inference to determine meaning.","questionTopics":["Vocabulary and diction","Vocabulary in context","Diction and precision","Register"],"video":{"title":"Using context clues to figure out new words","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=CiNggzdWkIo","source":"YouTube"},"questionCount":25},{"id":"roots-affixes","title":"Prefixes, Roots & Word Forms","summary":"Break unfamiliar words into meaningful parts and use form and spelling clues.","questionTopics":["Vocabulary and diction","Prefixes and roots","Word forms","Spelling","Commonly confused words"],"video":{"title":"Prefixes, Suffixes, and Word Roots - Video and Worksheet","channel":"English Units","url":"https://www.youtube.com/watch?v=1ffjfpMl9-4","source":"YouTube"},"questionCount":24},{"id":"analogies-word-relationships","title":"Analogies & Word Relationships","summary":"Identify the relationship between word pairs before applying the same relationship to a new pair.","questionTopics":["Vocabulary and diction","Analogies","Synonyms","Antonyms"],"video":{"title":"Learn English Vocabulary with Analogies & Critical Thinking","channel":"Woodward English","url":"https://www.youtube.com/watch?v=G8nHmnjEnYg","source":"YouTube"},"questionCount":23},{"id":"filipino-vocabulary-idioms","title":"Filipino Vocabulary & Idyoma","summary":"Recognize Filipino word meaning, relationships, and common idiomatic expressions.","questionTopics":["Filipino grammar and vocabulary","Filipino vocabulary","Filipino idioms","Filipino analogies"],"video":{"title":"Mga Idyoma","channel":"Teacher Aiza","url":"https://www.youtube.com/watch?v=tVOtRlra3wY","source":"YouTube"},"questionCount":23}],"studyGuide":{"intro":"Vocabulary questions are usually context questions. Use the sentence, word parts, tone, and relationships before relying on memorized definitions.","highYield":[{"title":"Vocabulary in Context & Precision","points":["Read the whole sentence or passage before choosing a meaning.","Substitute each answer choice into the sentence and check tone and logic.","Prefer the most precise word, not merely a roughly related one.","Register should match the audience and situation."],"formula":"Context + tone + grammar = best-fit meaning","example":{"question":"In 'The scientist gave a concise explanation,' what does concise most nearly mean?","steps":["The word describes an explanation.","A good explanation can be brief yet complete.","Choose the meaning brief and clear."],"answer":"Brief and clear"},"trap":"A familiar dictionary meaning may be wrong if it does not fit the sentence."},{"title":"Prefixes, Roots & Word Forms","points":["Prefixes change or refine meaning; suffixes often change grammatical function.","Roots can reveal a word family even if the full word is unfamiliar.","Check whether the sentence requires a noun, verb, adjective, or adverb.","Spelling and form matter because similar-looking words can function differently."],"formula":"prefix + root + suffix → meaning + grammatical role","example":{"question":"What does the prefix 'mis-' usually suggest in 'misinterpret'?","steps":["The root interpret means explain or understand.","The prefix mis- often means wrongly or badly."],"answer":"To interpret incorrectly"},"trap":"Knowing the root meaning is not enough; the sentence may require a different word form."},{"title":"Analogies, Synonyms & Antonyms","points":["State the relationship in the first pair before examining choices.","Possible relationships include part–whole, cause–effect, function, degree, synonym, and antonym.","The second pair must match the same relationship, not merely contain related words."],"formula":"A is to B as C is to ? → identify the relationship first","example":{"question":"Bird : nest :: bee : ?","steps":["A nest is a home built/used by a bird.","A hive is a home used by bees."],"answer":"Hive"},"trap":"Do not choose an answer because it belongs to the same topic; the relationship must match."},{"title":"Filipino Vocabulary & Idyoma","points":["Determine whether an expression is literal or idiomatic.","Use surrounding clues to infer Filipino word meaning.","For idyoma, interpret the accepted figurative meaning rather than the literal words.","Analogies in Filipino still require identifying the same logical relationship."],"formula":"Idyoma → figurative meaning, not literal translation","example":{"question":"Ano ang kahulugan ng 'bukás-palad'?","steps":["The expression is idiomatic.","It does not literally mean an open palm.","It describes someone generous."],"answer":"Mapagbigay"},"trap":"Literal translation is a common distractor in idiom questions."}],"quickRecall":["What should you read before deciding the meaning of a word in context?","What can a suffix tell you besides meaning?","What is the first step in solving an analogy?","Should an idiom usually be interpreted literally?"],"checklist":["I can infer word meaning using context and tone.","I can use prefixes, roots, suffixes, and word forms.","I can identify analogy relationships, synonyms, and antonyms.","I can interpret common Filipino vocabulary and idiomatic expressions."]}},{"id":"lang-r1","category":"Language & Reading","domain":"R1","title":"Reading Comprehension","access":"Premium","summary":"Answer from the passage rather than from background knowledge or personal opinion.","points":["Find the central claim and paragraph roles.","Distinguish stated details from inference.","Use evidence for tone and purpose.","Interpret tables together with surrounding text."],"practice":"R1","topics":[{"id":"main-idea-details","title":"Main Idea & Supporting Details","summary":"Identify the central idea first, then locate details that directly support it.","questionTopics":["Main idea","Supporting detail","Pangunahing ideya","Pangunahing pahayag","Detalye"],"video":{"title":"What is a main idea? | Reading","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=4swFGRhQoMI","source":"YouTube"},"questionCount":25},{"id":"inference","title":"Making Inferences","summary":"Combine text evidence with logical reasoning instead of guessing beyond the passage.","questionTopics":["Inference","Hinuha","Hinuha mula sa datos at teksto"],"video":{"title":"Making inferences in informational texts | Reading","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=gUW2jit3uvo","source":"YouTube"},"questionCount":14},{"id":"tone","title":"Tone & Word Choice","summary":"Use diction and connotation to identify how the author feels about the subject.","questionTopics":["Tone","Tono","Symbolism"],"video":{"title":"Analyzing tone through word choice | Reading","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=l3yWmXbC36s","source":"YouTube"},"questionCount":12},{"id":"authors-purpose","title":"Author's Purpose","summary":"Ask what the author wants the reader to know, believe, feel, or do.","questionTopics":["Author's purpose"],"video":{"title":"Analyzing an author's purpose | Reading","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=R_bgo8j6jxc","source":"YouTube"},"questionCount":1},{"id":"text-structure","title":"Text Structure & Organization","summary":"Recognize how ideas are arranged and how titles, data, and sections guide meaning.","questionTopics":["Passage organization","Organisasyon ng teksto","Best title","Pagsusuri ng pamagat","Pagbasa ng datos"],"video":{"title":"Comparing text structures | Reading","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=QVmqK6V2eag","source":"YouTube"},"questionCount":6},{"id":"reading-vocabulary-context","title":"Reading Vocabulary in Context","summary":"Use nearby evidence to determine a word or phrase's meaning inside the passage.","questionTopics":["Vocabulary in context","Talasalitaan sa konteksto"],"video":{"title":"Using context clues to determine the meaning of a word","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=k_vfm81eYD0","source":"YouTube"},"questionCount":12}],"studyGuide":{"intro":"Reading comprehension should be evidence-based. Answer from the passage, not from outside knowledge. Track the author's central idea, paragraph roles, evidence, tone, and purpose.","highYield":[{"title":"Main Idea & Supporting Details","points":["The main idea is the broad point the passage develops, not a single detail.","Supporting details explain, prove, illustrate, or develop the main idea.","A good main-idea answer covers most of the passage without becoming too broad.","Titles often reflect the central focus but should not introduce ideas absent from the text."],"formula":"Main idea = topic + author's central point about that topic","example":{"question":"A passage describes how community gardens improve food access, social ties, and local learning. What is the likely main idea?","steps":["All three details are benefits of community gardens.","The answer should include the shared broader point."],"answer":"Community gardens can strengthen communities in several ways."},"trap":"A vivid example from one paragraph is usually too narrow to be the main idea."},{"title":"Inference","points":["An inference must be supported by evidence even if it is not directly stated.","Combine textual clues with logical reasoning.","Reject answers that require assumptions beyond the passage."],"formula":"Text evidence + reasonable logic = inference","example":{"question":"A student checks the clock repeatedly and packs before the bell rings. What can reasonably be inferred?","steps":["Repeated clock-checking suggests attention to time.","Packing early suggests eagerness to leave."],"answer":"The student is anticipating the end of class."},"trap":"An inference is not a guess; there must be evidence in the text."},{"title":"Tone & Word Choice","points":["Tone is the author's attitude toward the subject or audience.","Look for emotionally loaded words, level of formality, and repeated descriptive choices.","Tone words should be specific: skeptical, hopeful, critical, objective, enthusiastic, etc."],"formula":"Diction + connotation + context → tone","example":{"question":"Words such as 'wasteful,' 'careless,' and 'avoidable' most strongly suggest what tone?","steps":["The words express negative judgment.","The author is evaluating the subject unfavorably."],"answer":"Critical"},"trap":"Topic and tone are different; a serious topic does not automatically mean the author's tone is angry or sad."},{"title":"Author's Purpose","points":["Ask what the author wants the reader to know, believe, feel, or do.","Common purposes include inform, explain, argue, persuade, compare, entertain, or reflect.","Use the passage's structure and evidence, not a single sentence."],"formula":"Purpose = intended effect on the reader","example":{"question":"A passage presents evidence for later school start times and ends with a recommendation. What is the likely purpose?","steps":["The author provides evidence.","The author recommends a change.","The goal is to persuade."],"answer":"To persuade readers to support later school start times."},"trap":"A passage can contain facts while still having a persuasive purpose."},{"title":"Text Structure & Organization","points":["Common structures include cause–effect, compare–contrast, problem–solution, sequence, and description.","Transition words often reveal relationships between ideas.","Ask what role each paragraph plays in the whole passage.","Tables and charts should be interpreted together with the surrounding text."],"formula":"Identify paragraph role → identify overall structure","example":{"question":"A passage describes traffic congestion, then presents public transport expansion as a response. What structure dominates?","steps":["The first section presents a problem.","The next section presents a response."],"answer":"Problem–solution"},"trap":"Do not label structure from one transition word alone; check the whole passage."},{"title":"Vocabulary in Context","points":["Use nearby definitions, examples, contrast words, and tone.","Replace the word with each answer choice and test the sentence.","The correct meaning may be a less common definition if the passage supports it."],"formula":"Nearby clues + sentence logic → contextual meaning","example":{"question":"If 'temper' appears in 'The trees temper the afternoon heat,' what does it most likely mean?","steps":["The trees affect the heat.","The context suggests reducing or moderating it."],"answer":"Reduce or moderate"},"trap":"Do not automatically choose the most familiar meaning of a multiple-meaning word."}],"quickRecall":["How is the main idea different from a supporting detail?","What makes an inference valid?","What language clues reveal tone?","What question should you ask to identify author's purpose?","Name two common text structures.","What should you do with an unfamiliar word before choosing a definition?"],"checklist":["I can distinguish central idea from supporting evidence.","I can make inferences that are directly supported by the passage.","I can identify tone using diction and connotation.","I can identify the author's purpose from the passage as a whole.","I can recognize major text structures and paragraph roles.","I can determine vocabulary meaning from context."]}},{"id":"science-s1","category":"Science","domain":"S1","title":"General, Earth & Environmental Science","access":"Free","summary":"Combine scientific-method reasoning with Earth, atmosphere, astronomy, and environmental systems.","points":["Separate variables from outcomes.","Track units in measurement questions.","Use plate-boundary and water-cycle models.","Connect environmental causes with effects."],"practice":"S1","topics":[{"id":"scientific-method","title":"Scientific Method & Experimental Design","summary":"Turn observations into testable questions, identify variables, and evaluate evidence from experiments.","questionTopics":["Scientific method","Experimental design"],"video":{"title":"The Scientific Method: Crash Course Biology #2","channel":"CrashCourse","url":"https://www.youtube.com/watch?v=xOLcZMw0hd4","source":"YouTube"},"questionCount":3},{"id":"density-measurement","title":"Density & Measurement","summary":"Relate mass and volume using density and use displacement to measure irregular objects.","questionTopics":["Density","Volume displacement","Mass and weight"],"video":{"title":"What Is Density?","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=LiXut4P0drg","source":"YouTube"},"questionCount":13},{"id":"plate-tectonics","title":"Plate Tectonics & Geologic Hazards","summary":"Connect plate boundaries with earthquakes, volcanoes, tsunamis, and related Earth processes.","questionTopics":["Plate tectonics","Earthquakes","Epicenter","Focus","Tsunamis","Volcanoes"],"video":{"title":"Introduction to Plate Tectonics","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=7jbwX1Uvd18","source":"YouTube"},"questionCount":6},{"id":"rock-cycle-surface","title":"Rock Cycle, Weathering & Erosion","summary":"Review how rocks change over time and how weathering, erosion, and deposition reshape Earth's surface.","questionTopics":["Rock cycle","Minerals","Weathering","Erosion","Weathering and erosion","Deposition"],"video":{"title":"The Rock Cycle","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=rmH4W92eHVM","source":"YouTube"},"questionCount":7},{"id":"weather-atmosphere","title":"Weather & the Atmosphere","summary":"Connect atmospheric layers, air movement, phase changes, and weather conditions.","questionTopics":["Atmosphere","Troposphere","Stratosphere","Ozone layer","Weather","Condensation","Evaporation","Convection","Heat transfer"],"video":{"title":"Weather | Weather and Climate","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=U5ikrkOGio0","source":"YouTube"},"questionCount":10},{"id":"moon-phases","title":"Moon Phases","summary":"Explain why the Moon appears to change shape as it orbits Earth.","questionTopics":["Moon phases","Rotation","Revolution"],"video":{"title":"Moon Phases: Crash Course Astronomy #4","channel":"CrashCourse","url":"https://www.youtube.com/watch?v=AQ5vty8f9Xc","source":"YouTube"},"questionCount":4},{"id":"eclipses","title":"Solar & Lunar Eclipses","summary":"Use Sun-Earth-Moon alignment to distinguish solar and lunar eclipses.","questionTopics":["Eclipses","Lunar eclipse","Solar eclipse"],"video":{"title":"Eclipses: Crash Course Astronomy #5","channel":"CrashCourse","url":"https://www.youtube.com/watch?v=PRgua7xceDA","source":"YouTube"},"questionCount":3},{"id":"tides","title":"Tides","summary":"Relate high and low tides to gravity and the relative positions of Earth, Moon, and Sun.","questionTopics":["Tides","Spring tides"],"video":{"title":"Tides: Crash Course Astronomy #8","channel":"CrashCourse","url":"https://www.youtube.com/watch?v=KlWpFLfLFBI","source":"YouTube"},"questionCount":2}],"studyGuide":{"intro":"Build a strong Earth-and-general-science foundation by connecting observations to models. Focus on variables, measurement, Earth processes, atmosphere, and Sun–Earth–Moon relationships.","highYield":[{"title":"Scientific Method & Experimental Design","points":["A testable hypothesis predicts how one variable may affect another.","The independent variable is deliberately changed; the dependent variable is measured.","Controlled variables are kept constant so the comparison is fair.","Repeated trials and larger samples generally make results more reliable."],"formula":"Change one factor → measure the response → keep other relevant factors controlled.","example":{"question":"A student tests whether fertilizer amount affects plant height. What is the dependent variable?","steps":["The fertilizer amount is the factor being changed.","Plant height is the outcome being measured."],"answer":"Plant height"},"trap":"Do not confuse the variable you change with the variable you measure."},{"title":"Density & Measurement","points":["Density compares mass with volume.","For a regular object, volume can come from geometric formulas; irregular objects can use water displacement.","Mass and weight are different: mass measures matter, while weight is a gravitational force.","Always keep units consistent before calculating."],"formula":"density = mass / volume","example":{"question":"A sample has a mass of 120 g and a volume of 40 cm³. Find its density.","steps":["Use density = mass ÷ volume.","120 ÷ 40 = 3."],"answer":"3 g/cm³"},"trap":"Do not divide volume by mass; density is mass per unit volume."},{"title":"Plate Tectonics & Geologic Hazards","points":["Earth's lithosphere is divided into moving tectonic plates.","Convergent boundaries can create trenches, mountains, and volcanic arcs.","Divergent boundaries form new crust; transform boundaries involve sliding motion.","Earthquakes begin at the focus; the epicenter is the point on the surface directly above it."],"formula":"Plate motion → stress/release or magma movement → geologic activity","example":{"question":"What is the point on Earth's surface directly above an earthquake's focus?","steps":["The focus is underground where rupture begins.","The corresponding surface point is the epicenter."],"answer":"Epicenter"},"trap":"The focus and epicenter are related but are not the same location."},{"title":"Rock Cycle, Weathering & Erosion","points":["Weathering breaks rock down; erosion transports the broken material.","Deposition occurs when transported sediment settles.","Igneous rock forms from cooled magma/lava, sedimentary rock from compacted/cemented sediments, and metamorphic rock from heat and pressure.","Rocks can move through the rock cycle in multiple pathways."],"formula":"Weathering → erosion → transport → deposition","example":{"question":"River water carries sand downstream and later drops it on a riverbank. Which process is the dropping of sediment?","steps":["Carrying the sand is erosion/transport.","Dropping and settling is deposition."],"answer":"Deposition"},"trap":"Weathering breaks material apart; erosion moves it."},{"title":"Weather & the Atmosphere","points":["Most weather occurs in the troposphere.","The stratosphere contains much of the ozone layer.","Evaporation changes liquid water to gas; condensation changes gas to liquid.","Convection transfers heat through bulk movement in fluids such as air."],"formula":"Warm air rises; cool air sinks → convection circulation","example":{"question":"Cloud droplets form when water vapor cools and changes into liquid. What process is this?","steps":["The change is gas to liquid.","That phase change is condensation."],"answer":"Condensation"},"trap":"Evaporation and condensation are opposite phase changes."},{"title":"Moon Phases","points":["Moon phases are caused by changing viewing geometry as the Moon orbits Earth.","Half of the Moon is illuminated by the Sun at nearly all times.","The visible illuminated fraction changes from our viewpoint.","A complete cycle of phases takes about one synodic month."],"formula":"Phase depends on Sun–Earth–Moon geometry, not Earth's shadow.","example":{"question":"Why does the Moon appear to change shape during the month?","steps":["The Moon orbits Earth.","We see different portions of its sunlit half."],"answer":"Changing viewing geometry as the Moon revolves around Earth"},"trap":"Normal Moon phases are not caused by Earth's shadow; Earth's shadow is involved in a lunar eclipse."},{"title":"Solar & Lunar Eclipses","points":["A solar eclipse occurs when the Moon is between Earth and the Sun.","A lunar eclipse occurs when Earth is between the Sun and Moon.","Eclipses do not occur every month because the Moon's orbit is tilted relative to Earth's orbital plane."],"formula":"Solar: Sun–Moon–Earth · Lunar: Sun–Earth–Moon","example":{"question":"During which event does Earth block sunlight from reaching the Moon?","steps":["Earth must be between the Sun and Moon.","That alignment produces a lunar eclipse."],"answer":"Lunar eclipse"},"trap":"Do not reverse the two alignments."},{"title":"Tides","points":["Tides are driven mainly by the Moon's gravity, with the Sun also contributing.","Spring tides occur when Sun, Earth, and Moon are approximately aligned.","Neap tides occur when the Sun and Moon pull at roughly right angles relative to Earth.","Spring tide refers to a larger tidal range, not the season spring."],"formula":"Aligned gravitational pulls → larger tidal range","example":{"question":"When are spring tides expected?","steps":["Spring tides require aligned pulls.","This happens near new moon and full moon."],"answer":"Near new moon and full moon"},"trap":"Spring tides are named for 'springing forth,' not for the season."}],"quickRecall":["Which variable is deliberately changed in an experiment?","What is the formula for density?","How are focus and epicenter different?","What is the difference between weathering and erosion?","In which atmospheric layer does most weather occur?","What actually causes Moon phases?","What is the alignment for a lunar eclipse?","When do spring tides occur?"],"checklist":["I can identify variables and controls in an experiment.","I can solve density and displacement problems with correct units.","I can connect plate boundaries with earthquakes and volcanoes.","I can distinguish weathering, erosion, and deposition.","I can explain basic atmospheric and phase-change processes.","I can explain Moon phases without confusing them with eclipses.","I can distinguish solar and lunar eclipse geometry.","I can explain why spring tides have a larger tidal range."]}},{"id":"science-s2","category":"Science","domain":"S2","title":"Biology","access":"Free","summary":"Study living systems from molecules to ecosystems.","points":["Match organelles with functions.","Trace matter and energy through cells.","Use allele combinations carefully.","Connect structure, function, and homeostasis."],"practice":"S2","topics":[{"id":"cell-organelles","title":"Cells & Organelles","summary":"Match major cell structures with their functions and compare common cell types.","questionTopics":["Cell organelles","Cell membrane","Cell types","Golgi apparatus","Lysosome","Mitochondrion","Nucleus","Ribosome","Chloroplast"],"video":{"title":"Cell Organelles and Structures Review","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=6mgkoqcm6Sg","source":"YouTube"},"questionCount":16},{"id":"photosynthesis","title":"Photosynthesis","summary":"Follow how plants use light energy to make glucose and connect chloroplast structure with function.","questionTopics":["Photosynthesis","Chloroplast"],"video":{"title":"Photosynthesis (UPDATED)","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=CMiPYHNNg28","source":"YouTube"},"questionCount":3},{"id":"cellular-respiration","title":"Cellular Respiration","summary":"Review how cells release usable energy from glucose and why mitochondria are important.","questionTopics":["Cellular respiration","Mitochondrion"],"video":{"title":"Cellular Respiration (UPDATED)","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=eJ9Zjc-jdys","source":"YouTube"},"questionCount":3},{"id":"genetics-heredity","title":"Genetics & Heredity","summary":"Connect DNA, genes, alleles, inheritance patterns, mutations, and Punnett-square reasoning.","questionTopics":["DNA","Mendelian genetics","Mutation","Reproduction","Asexual reproduction","Genetics and ecology"],"video":{"title":"Mega Genetics Review: Mendelian and non-Mendelian Genetics","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=jLmoJPxihjA","source":"YouTube"},"questionCount":15},{"id":"human-body-systems","title":"Human Body Systems","summary":"Review how major organ systems work together to maintain normal body function.","questionTopics":["Alveoli","Digestive system","Endocrine system","Homeostasis","Levels of organization","Respiratory system","Small intestine"],"video":{"title":"Human Body Systems Overview (Updated 2024)","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=0JDCViWGn-0","source":"YouTube"},"questionCount":9},{"id":"ecology-symbiosis","title":"Ecology & Symbiosis","summary":"Distinguish competition, predation, mutualism, commensalism, and parasitism in ecosystems.","questionTopics":["Ecology","Symbiosis"],"video":{"title":"Ecological Relationships","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=rNjPI84sApQ","source":"YouTube"},"questionCount":2},{"id":"evolution-classification","title":"Evolution & Classification","summary":"Review mechanisms of evolutionary change and connect biological similarities with classification.","questionTopics":["Evolution","Taxonomy","Animal classification"],"video":{"title":"Evolution","channel":"Amoeba Sisters","url":"https://www.youtube.com/watch?v=fI7IV3x-dGI","source":"YouTube"},"questionCount":3}],"studyGuide":{"intro":"Biology questions often test structure–function relationships. Know what cell parts do, how energy and information move through living systems, and how organisms interact with their environment.","highYield":[{"title":"Cells & Organelles","points":["The nucleus stores most genetic information in eukaryotic cells.","Ribosomes build proteins; mitochondria make most cellular ATP through respiration.","The Golgi apparatus modifies and packages cell products; lysosomes help digest materials.","Plant cells commonly have chloroplasts and a cell wall in addition to a cell membrane."],"formula":"Structure → function: identify what the organelle does before choosing it.","example":{"question":"Which organelle is most directly responsible for protein synthesis?","steps":["Protein synthesis occurs on ribosomes.","Ribosomes may be free or attached to rough ER."],"answer":"Ribosome"},"trap":"Do not choose mitochondria for every energy-related or protein-related cell question; match the specific function."},{"title":"Photosynthesis","points":["Photosynthesis stores light energy in chemical bonds of glucose.","It occurs mainly in chloroplasts.","Carbon dioxide and water are reactants; glucose and oxygen are products in the simplified overall equation.","Light-dependent reactions capture energy; the Calvin cycle uses that energy to build carbohydrates."],"formula":"6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂","example":{"question":"Which gas is consumed during photosynthesis?","steps":["Carbon dioxide is a reactant.","Oxygen is a major product."],"answer":"Carbon dioxide"},"trap":"Plants perform cellular respiration too; photosynthesis does not replace respiration."},{"title":"Cellular Respiration","points":["Cellular respiration releases usable energy from glucose.","Aerobic respiration uses oxygen and produces carbon dioxide and water.","Most ATP in aerobic respiration is produced through processes associated with mitochondria.","Respiration is performed by both plants and animals."],"formula":"C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP","example":{"question":"What is the main purpose of cellular respiration?","steps":["Cells need a usable energy currency.","Respiration transfers energy from glucose into ATP."],"answer":"To produce ATP for cellular work"},"trap":"Cellular respiration is not the same as breathing; breathing supplies gases for the cellular process."},{"title":"Genetics & Heredity","points":["Genes are segments of DNA; alleles are alternative forms of a gene.","Genotype describes allele combinations; phenotype describes observable traits.","A Punnett square predicts possible offspring genotypes, not guaranteed outcomes.","Mutations are changes in genetic material and can be neutral, harmful, or beneficial."],"formula":"Genotype + environment → phenotype","example":{"question":"If T is dominant and t is recessive, what fraction of offspring from Tt × Tt are expected to be tt?","steps":["Possible genotypes: TT, Tt, Tt, tt.","One of four is tt."],"answer":"1/4 or 25%"},"trap":"A probability from a Punnett square does not mean every group of four offspring will follow that exact pattern."},{"title":"Human Body Systems & Homeostasis","points":["The respiratory system exchanges oxygen and carbon dioxide; alveoli provide a large surface area for gas exchange.","The digestive system breaks food down and absorbs nutrients; much nutrient absorption occurs in the small intestine.","The endocrine system uses hormones for longer-range chemical signaling.","Homeostasis keeps internal conditions within workable ranges through regulation."],"formula":"Stimulus → sensor/control → response → restored internal balance","example":{"question":"Why are alveoli effective for gas exchange?","steps":["They are numerous and thin-walled.","This creates a large surface area and short diffusion distance."],"answer":"Large surface area and thin exchange surfaces"},"trap":"Do not confuse where digestion occurs with where most nutrient absorption occurs."},{"title":"Ecology & Symbiosis","points":["Mutualism benefits both organisms; commensalism benefits one with little/no effect on the other; parasitism benefits one and harms the other.","Energy enters many ecosystems through producers and moves through food chains/webs.","Populations are members of one species; communities contain multiple populations.","Environmental limits can affect population size and survival."],"formula":"Identify who benefits, who is harmed, and who is unaffected.","example":{"question":"A tick feeds on a dog and harms it. What relationship is this?","steps":["The tick benefits.","The dog is harmed."],"answer":"Parasitism"},"trap":"Not every close relationship between species is mutualism."},{"title":"Evolution & Classification","points":["Natural selection changes trait frequencies across generations when heritable variation affects survival or reproduction.","Individuals do not evolve during their lifetime; populations evolve over generations.","Classification groups organisms using shared characteristics and evolutionary relationships.","Taxonomic ranks become increasingly specific from kingdom toward species."],"formula":"Heritable variation + differential reproduction + generations → evolutionary change","example":{"question":"Why can an antibiotic-resistant bacterial trait become common?","steps":["Some bacteria already vary in resistance.","Antibiotics remove more susceptible bacteria.","Resistant survivors reproduce and pass on resistance-related traits."],"answer":"Natural selection increases the frequency of resistant variants."},"trap":"Organisms do not develop a needed trait simply because the environment 'makes them try.'"}],"quickRecall":["Which organelle builds proteins?","What gas is used during photosynthesis?","What is the main energy product of cellular respiration?","What is the difference between genotype and phenotype?","Where does most nutrient absorption occur?","How do mutualism and parasitism differ?","Do individuals or populations evolve?"],"checklist":["I can match major organelles with their functions.","I can identify reactants and products of photosynthesis.","I can explain the purpose and basic equation of cellular respiration.","I can solve simple Mendelian inheritance questions.","I can connect major body-system structures with their functions.","I can identify common ecological relationships.","I can explain natural selection and basic classification."]}},{"id":"science-s3","category":"Science","domain":"S3","title":"Chemistry","access":"Premium","summary":"Move between particles, symbols, formulas, and measurable quantities.","points":["Atomic number gives proton count.","Balance equations before using mole ratios.","Use Kelvin for gas-law temperature.","Check whether a process is physical or chemical."],"practice":"S3","topics":[{"id":"atomic-structure","title":"Atomic Structure & the Periodic Table","summary":"Identify protons, neutrons, electrons, ions, isotopes, and periodic-table information.","questionTopics":["Atomic structure","Electron configuration","Ions","Isotopes","Periodic table","Valence electrons"],"video":{"title":"Atoms - Basic Introduction","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=acdkMeEKCNQ","source":"YouTube"},"questionCount":16},{"id":"chemical-bonding","title":"Ionic & Covalent Bonding","summary":"Distinguish electron transfer from electron sharing and identify common ionic and covalent compounds.","questionTopics":["Ionic Bond","Ionic bonding","Covalent Bond","Covalent bonding"],"video":{"title":"Introduction to Ionic Bonding and Covalent Bonding","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=S_k0kr2eZSQ","source":"YouTube"},"questionCount":4},{"id":"mole-stoichiometry","title":"The Mole, Equations & Stoichiometry","summary":"Move between mass and moles, use balanced equations, and apply mole ratios.","questionTopics":["The mole","Molar mass","Balancing equations","Conservation of mass","Stoichiometry"],"video":{"title":"Stoichiometry: Mass-to-Mass and Limiting Reagent","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=5O083FL_9u8","source":"YouTube"},"questionCount":5},{"id":"gas-laws","title":"Gas Laws","summary":"Relate pressure, volume, temperature, and amount using Boyle's, Charles's, and combined gas laws.","questionTopics":["Boyle's law","Charles's law","Combined gas law"],"video":{"title":"Gas Laws - Equations and Formulas","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=IE8-izIba40","source":"YouTube"},"questionCount":13},{"id":"acids-bases","title":"Acids, Bases & Neutralization","summary":"Recognize acid/base behavior and understand what happens during neutralization.","questionTopics":["Acid","Base","Acids and bases","Neutralization"],"video":{"title":"Intro to Acids and Bases","channel":"Khan Academy","url":"https://www.youtube.com/watch?v=ja7p_tzTTEA","source":"YouTube"},"questionCount":5}],"studyGuide":{"intro":"Chemistry rewards careful tracking of particles, charge, ratios, and units. Move smoothly between atomic structure, bonding, equations, moles, gases, and acid–base behavior.","highYield":[{"title":"Atomic Structure & the Periodic Table","points":["Atomic number equals the number of protons.","A neutral atom has equal numbers of protons and electrons.","Isotopes have the same number of protons but different numbers of neutrons.","Ions form when atoms gain or lose electrons; valence electrons strongly influence bonding."],"formula":"mass number = protons + neutrons","example":{"question":"An atom has atomic number 8 and mass number 16. How many neutrons does it have?","steps":["Atomic number gives 8 protons.","Neutrons = 16 − 8."],"answer":"8 neutrons"},"trap":"Changing electrons makes an ion, not a different element; changing protons changes the element."},{"title":"Ionic & Covalent Bonding","points":["Ionic bonding is associated with electron transfer and attraction between oppositely charged ions.","Covalent bonding involves sharing electron pairs between atoms.","Metals commonly form positive ions; nonmetals commonly form negative ions in simple ionic compounds.","Bond type helps predict properties such as conductivity and melting behavior."],"formula":"Ionic: electron transfer · Covalent: electron sharing","example":{"question":"What type of bonding is expected between sodium and chlorine?","steps":["Sodium is a metal and tends to lose an electron.","Chlorine is a nonmetal and tends to gain an electron.","The resulting ions attract."],"answer":"Ionic bonding"},"trap":"A molecule containing different elements is not automatically ionic; many are covalent."},{"title":"The Mole, Equations & Stoichiometry","points":["One mole contains Avogadro's number of representative particles.","Molar mass converts between grams and moles.","Chemical equations must be balanced before mole ratios are used.","Stoichiometric coefficients give relative mole ratios, not mass ratios."],"formula":"moles = mass / molar mass","example":{"question":"How many moles are in 36 g of water if its molar mass is 18 g/mol?","steps":["Use moles = mass ÷ molar mass.","36 ÷ 18 = 2."],"answer":"2 mol"},"trap":"Do not use an unbalanced equation for stoichiometric ratios."},{"title":"Gas Laws","points":["Boyle's law describes an inverse pressure–volume relationship at constant temperature.","Charles's law describes a direct volume–temperature relationship at constant pressure.","Gas-law temperature calculations use an absolute scale such as Kelvin.","The combined gas law relates pressure, volume, and temperature between two states."],"formula":"Boyle: P₁V₁=P₂V₂ · Charles: V₁/T₁=V₂/T₂","example":{"question":"At constant temperature, a gas has 2.0 L at 1 atm. What volume at 2 atm?","steps":["Use P₁V₁ = P₂V₂.","1(2.0) = 2(V₂).","V₂ = 1.0 L."],"answer":"1.0 L"},"trap":"Do not use Celsius directly in gas-law ratios that require absolute temperature."},{"title":"Acids, Bases & Neutralization","points":["Acids increase H⁺/H₃O⁺ concentration in aqueous solution; bases increase OH⁻ or accept protons depending on the model used.","Lower pH is more acidic; higher pH is more basic on the usual aqueous pH scale.","Neutralization combines acid and base behavior and commonly forms water plus a salt.","Indicators change color over characteristic pH ranges."],"formula":"acid + base → salt + water (common neutralization pattern)","example":{"question":"What generally happens when a strong acid and strong base react in equivalent amounts?","steps":["H⁺ and OH⁻ combine to form water.","The remaining ions form a salt."],"answer":"Neutralization produces water and a salt."},"trap":"Neutral does not mean 'no ions'; a neutral solution can still contain dissolved ions."}],"quickRecall":["What does atomic number tell you?","How do ionic and covalent bonds differ?","What must be done before using coefficients as mole ratios?","What temperature scale should be used in gas-law ratios?","What are common products of acid–base neutralization?"],"checklist":["I can determine protons, neutrons, electrons, ions, and isotopes.","I can distinguish ionic from covalent bonding.","I can convert between mass and moles and use balanced equations.","I can choose and apply basic gas-law relationships.","I can identify acid/base behavior and explain neutralization."]}},{"id":"science-s4","category":"Science","domain":"S4","title":"Physics","access":"Premium","summary":"Translate a situation into a diagram, relationship, and unit-aware calculation.","points":["Distinguish scalar and vector quantities.","Choose the correct force or energy model.","Use slopes on motion graphs.","Apply circuit rules and Ohm's law."],"practice":"S4","topics":[{"id":"newtons-laws-motion","title":"Newton's Laws & Motion","summary":"Connect net force, mass, acceleration, inertia, friction, and motion descriptions.","questionTopics":["Acceleration","Displacement","Friction","Inertia","Motion graphs","Newton's first law","Newton's second law","Scalars and vectors","Speed","Weight"],"video":{"title":"Newton's Second Law of Motion - Force, Mass, & Acceleration","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=Ee6CHn0MRKE","source":"YouTube"},"questionCount":20},{"id":"work-energy-power","title":"Work, Energy & Power","summary":"Relate work to energy transfer and distinguish kinetic energy, potential energy, and power.","questionTopics":["Conservation of energy","Kinetic energy","Potential energy","Power","Work"],"video":{"title":"Work, Energy, and Power - Basic Introduction","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=_MR1Dp8-F8w","source":"YouTube"},"questionCount":6},{"id":"momentum","title":"Momentum","summary":"Use p = mv and connect changes in momentum with force and collisions.","questionTopics":["Momentum"],"video":{"title":"Momentum - Basic Introduction","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=NIVNfI0RN2k","source":"YouTube"},"questionCount":2},{"id":"fluids-buoyancy","title":"Pressure, Fluids & Buoyancy","summary":"Connect fluid pressure, density, displacement, and buoyant force using Archimedes' principle.","questionTopics":["Pressure","Buoyancy","Buoyant Force"],"video":{"title":"Fluid Pressure, Density, Archimedes' Principle & Buoyant Force","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=nUKUzpRgdbY","source":"YouTube"},"questionCount":4},{"id":"waves-sound","title":"Waves & Sound","summary":"Relate wavelength, frequency, and wave speed and distinguish common types of mechanical waves.","questionTopics":["Frequency","Sound","Wave speed"],"video":{"title":"Transverse and Longitudinal Waves","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=vEzftaDL7fM","source":"YouTube"},"questionCount":3},{"id":"electricity-ohms-law","title":"Electric Circuits & Ohm's Law","summary":"Use voltage, current, and resistance relationships to solve basic circuit problems.","questionTopics":["Electric circuits","Ohm's law","Parallel Circuit"],"video":{"title":"Electricity - Voltage, Current, and Resistance - Ohm's Law","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=NqV6Get9FZA","source":"YouTube"},"questionCount":13},{"id":"heat-transfer","title":"Heat Transfer","summary":"Distinguish conduction, convection, and radiation and identify how thermal energy moves.","questionTopics":["Conduction","Convection","Heat transfer"],"video":{"title":"Heat Transfer - Conduction, Convection, and Radiation","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=bRZwzy0xvhM","source":"YouTube"},"questionCount":3}],"studyGuide":{"intro":"Physics is about choosing the right model. Draw or describe the situation, identify known quantities and units, then use the relationship that directly connects them.","highYield":[{"title":"Newton's Laws & Motion","points":["Newton's first law describes inertia: motion changes only when a net external force acts.","Newton's second law relates net force, mass, and acceleration.","Acceleration is the rate of change of velocity, not simply 'moving fast.'","Weight is a gravitational force; mass is the amount of matter/inertia."],"formula":"F_net = ma","example":{"question":"A 5 kg object has a net force of 20 N. Find its acceleration.","steps":["Use a = F/m.","20 ÷ 5 = 4."],"answer":"4 m/s²"},"trap":"Use net force, not just one individual force, in F = ma."},{"title":"Work, Energy & Power","points":["Work is done when a force causes displacement in the force's direction.","Kinetic energy depends on mass and speed; gravitational potential energy depends on mass, gravity, and height.","Energy can transform while total energy is conserved in an isolated idealized system.","Power measures how quickly work is done or energy is transferred."],"formula":"W=Fd (parallel force) · KE=½mv² · PE=mgh · P=W/t","example":{"question":"A machine does 600 J of work in 3 s. Find its power.","steps":["Use P = W/t.","600 ÷ 3 = 200."],"answer":"200 W"},"trap":"Doing the same work in less time means greater power, not greater total work."},{"title":"Momentum","points":["Momentum depends on both mass and velocity and has direction.","In an isolated system, total momentum is conserved through collisions.","A force acting over time changes momentum."],"formula":"p = mv","example":{"question":"Find the momentum of a 3 kg object moving at 4 m/s.","steps":["Use p = mv.","3 × 4 = 12."],"answer":"12 kg·m/s"},"trap":"Because velocity has direction, momentum also has direction."},{"title":"Pressure, Fluids & Buoyancy","points":["Pressure is force distributed over area.","Fluid pressure generally increases with depth.","Buoyant force equals the weight of displaced fluid in Archimedes' principle.","An object floats when the buoyant force balances its weight under stable conditions."],"formula":"P=F/A · F_b = weight of displaced fluid","example":{"question":"A force of 100 N acts over an area of 0.5 m². Find the pressure.","steps":["Use P = F/A.","100 ÷ 0.5 = 200."],"answer":"200 Pa"},"trap":"Increasing contact area lowers pressure for the same force."},{"title":"Waves & Sound","points":["Wave speed equals frequency times wavelength.","Frequency is the number of cycles per second and is measured in hertz.","Sound is a mechanical wave and requires a medium.","Amplitude is associated with wave intensity; frequency is associated with pitch for sound."],"formula":"v = fλ","example":{"question":"A wave has frequency 5 Hz and wavelength 2 m. Find its speed.","steps":["Use v = fλ.","5 × 2 = 10."],"answer":"10 m/s"},"trap":"Higher frequency does not automatically mean higher wave speed; speed depends on the medium and wave type."},{"title":"Electric Circuits & Ohm's Law","points":["Voltage is electric potential difference; current is charge flow; resistance opposes current.","Ohm's law relates voltage, current, and resistance for ohmic conditions.","In a simple parallel circuit, branches share the same voltage.","Current divides among parallel branches."],"formula":"V = IR","example":{"question":"A 12 V source is connected to a 4 Ω resistor. Find the current.","steps":["Use I = V/R.","12 ÷ 4 = 3."],"answer":"3 A"},"trap":"Do not confuse current with voltage; they are different physical quantities with different units."},{"title":"Heat Transfer","points":["Conduction transfers thermal energy through direct microscopic interactions, especially in solids.","Convection transfers thermal energy through bulk motion of fluids.","Radiation transfers energy by electromagnetic waves and does not require a material medium.","Thermal energy spontaneously flows from hotter regions toward cooler regions."],"formula":"Conduction = contact · Convection = fluid motion · Radiation = electromagnetic waves","example":{"question":"Warm air rises while cooler air sinks in a room. Which heat-transfer process dominates?","steps":["The transfer involves bulk movement of air.","Air is a fluid."],"answer":"Convection"},"trap":"Convection occurs in fluids; solids mainly transfer heat by conduction."}],"quickRecall":["What force should be used in F = ma?","How are work and power different?","What two quantities determine momentum?","How does pressure change when the same force acts over a larger area?","What equation relates wave speed, frequency, and wavelength?","What does Ohm's law relate?","Which heat-transfer method can travel through empty space?"],"checklist":["I can use Newton's laws and distinguish mass, weight, velocity, and acceleration.","I can solve basic work, energy, and power problems.","I can calculate momentum and apply basic conservation reasoning.","I can solve simple pressure and buoyancy questions.","I can relate wave speed, frequency, wavelength, and sound properties.","I can apply Ohm's law and basic parallel-circuit ideas.","I can distinguish conduction, convection, and radiation."]}},{"id":"reason-r1","category":"Reasoning","domain":"R1","title":"Number Sequences","access":"Free","summary":"Test simple consistent rules before assuming a complicated pattern.","points":["Check differences and ratios.","Look for alternating subpatterns.","Use all given terms.","Verify the rule predicts more than one step."],"practice":"R1","topics":[{"id":"number-sequences","title":"Number Sequences","summary":"Test differences, ratios, alternating rules, powers, and repeated operations before choosing the next term.","questionTopics":["Number sequence"],"video":{"title":"Number Series Reasoning Tricks - The Easy Way!","channel":"The Organic Chemistry Tutor","url":"https://www.youtube.com/watch?v=r614AD021n0","source":"YouTube"},"questionCount":50}]},{"id":"reason-r2","category":"Reasoning","domain":"R2","title":"Figure Rotation","access":"Free","summary":"Track orientation with fixed angle increments.","points":["Choose a reference direction.","Record clockwise or counterclockwise motion.","Check whether shading also changes.","Ignore decorative features that remain constant."],"practice":"R2","topics":[{"id":"figure-rotation","title":"Figure Rotation","summary":"Track one reference feature at a time and determine the angle and direction of each rotation.","questionTopics":["Figure rotation"],"video":{"title":"11 Plus Non Verbal Reasoning - Type 11 - Figure Rotation - Part 1","channel":"Lessonade","url":"https://www.youtube.com/watch?v=o45pFWI2G9g","source":"YouTube"},"questionCount":50}]},{"id":"reason-r3","category":"Reasoning","domain":"R3","title":"Shape Progression","access":"Premium","summary":"Count elements and identify what is added, removed, or transformed.","points":["Count before interpreting.","Track shape, fill, size, and position separately.","Look for alternating changes.","Test the rule on every panel."],"practice":"R3","topics":[{"id":"shape-progression","title":"Shape Progression","summary":"Separate changes in shape, count, shading, orientation, size, and position to identify the next figure.","questionTopics":["Shape progression"],"video":{"title":"Figure Series Test | Non Verbal Reasoning","channel":"Decode Subject","url":"https://www.youtube.com/watch?v=f-75pgrQmbc","source":"YouTube"},"questionCount":50}]},{"id":"reason-r4","category":"Reasoning","domain":"R4","title":"Odd One Out","access":"Premium","summary":"State the shared rule of three figures, then identify the exception.","points":["Compare one property at a time.","Do not choose the most visually striking figure automatically.","Check rotation equivalence.","Distinguish count from arrangement."],"practice":"R4","topics":[{"id":"odd-one-out","title":"Odd One Out","summary":"Find the rule shared by most figures, then identify the one that breaks it instead of choosing by appearance alone.","questionTopics":["Odd one out"],"video":{"title":"11 Plus Genie Non-verbal Reasoning - NVR Type 2: Odd one out","channel":"11PlusGenie","url":"https://www.youtube.com/watch?v=YSBOr1To6Bk","source":"YouTube"},"questionCount":40}]},{"id":"reason-r5","category":"Reasoning","domain":"R5","title":"Matrix & Position","access":"Premium","summary":"Treat rows and columns as transformations or combinations.","points":["Label positions.","Compare across rows and down columns.","Look for union, subtraction, or rotation.","Verify the missing panel satisfies both directions."],"practice":"R5","topics":[{"id":"position-movement","title":"Position & Movement","summary":"Track how objects move between corners, sides, and relative positions while separating movement from rotation or other changes.","questionTopics":["Position movement"],"video":{"title":"Non Verbal Reasoning Test Tips and Tricks for Job Tests & Interviews","channel":"CareerVidz","url":"https://www.youtube.com/watch?v=CzMbznbN3xk","source":"YouTube"},"questionCount":30}]}];
